    var totalBudget = 1300;
    var fixedCost = 220;
    var unitCost = 35;
    var benefitPoints = 12;
    var minUnits = 10;
    var addOnCost = 200;
    var addOnBenefitPoints = 60;

    // Calculate the total cost of the plan without the add-on
    var totalWithoutAddOn = (totalBudget - fixedCost) / unitCost;

    // Calculate the total cost of the plan with the add-on
    var totalWithAddOn = (totalBudget + addOnCost) / unitCost;

    // Determine which plan maximizes benefit without exceeding the budget and while meeting the minimum-unit requirement
    if (totalWithoutAddOn <= totalBudget && totalWithoutAddOn >= minUnits) {
        return "Plan without add-on: " + totalWithoutAddOn.toFixed(2) + " CU";
    } else if (totalWithAddOn <= totalBudget && totalWithAddOn >= minUnits) {
