@answer jsEval {
    let routeA = new Route(times[0], capacities[0]);
    let routeB = new Route(times[1], capacities[1]);
    let routeC = new Route(times[2], capacities[2]);

    // Check if the total route time is within the limit
    if (routeA.totalTime + routeB.totalTime + routeC.totalTime > 37) {
        return "Route A is not feasible";
    }

    // Find the route with the minimum flow capacity
    let minFlowCapacity = Math.min(routeA.flowCapacity, routeB.flowCapacity, routeC.flowCapacity);
    let fastestRoute = minFlowCapacity === routeA.flowCapacity ? routeA : (minFlowCapacity === routeB.flowCapacity ? routeB : routeC);

    return fastestRoute.name;
}
