@answer jsEval (function() {
    var water = 5;
    var asWaterVapor = 5;
    var inMixture = 14;

    // Move 2 units from the compartment "in container" to the compartment "as water vapor"
    water += 2;
    asWaterVapor += 2;

    // Move 2 units from "as water vapor" to the compartment "in mixture"
    water -= 2;
    inMixture -= 2;

    // Check if the total has been conserved
    return water + asWaterVapor + inMixture === 24;
})

