@slots 1, 2, 3, 4
@facts 5, 2, 5
@answer jsEval (function() {
    var scores = [5, 2, 5, 2];
    var options = [
        { score: scores[0], name: "Option A" },
        { score: scores[1], name: "Option B" },
        { score: scores[2], name: "Option C" },
        { score: scores[3], name: "Option D" }
    ];

    var dominatedOptions = [];

    for (var i = 0; i < options.length; i++) {
        var currentScore = options[i].score;
        var isDominated = true;

        for (var j = 0; j < options.length; j++) {
            if (i !== j && options[j].score >= currentScore) {
                isDominated = false;
                break;
            }
        }

        if (isDominated) {
            dominatedOptions.push(options[i]);
        }
    }

    var uniqueWinner = null;

    for (var i = 0; i < options.length; i++) {
        if (!dominatedOptions.includes(options[i])) {
            if (uniqueWinner === null || options[i].score > uniqueWinner.score) {
                uniqueWinner = options[i];
            }
        }
    }

    return uniqueWinner;
})

