```soplang
@slots Cedar, Oak, Stone, Meadow, Capacity
@facts Cedar→Stone capacity 9, Stone→Oak capacity 6; Cedar→Meadow capacity 4, Meadow→Oak capacity 8
@answer jsEval (function() {
    let maxCapacity = 0;
    let bottleneck = [];

    // Calculate the maximum capacity of the branch with the smallest edge capacity
    for (let i = 0; i < Cedar.length; i++) {
        if ( Cedar[i] < Capacity[i]) {
            maxCapacity = Cedar[i];
            bottleneck.push(Cedar[i]);
        }
    }

    // Determine the bottleneck(s)
    if (bottleneck.length > 1) {
        return "Bottlenecks: " + bottleneck.join(", ");
    } else {
        return "Bottleneck: " + bottleneck[0];
    }
});
```

