@slots
var students = ['Ava', 'Ben', 'Cara', 'Dion'];
var tasks = ['Map', 'Budget', 'Survey', 'Timeline'];
var allowedTasks = ['Map', 'Survey'];
var quorumThreshold = 9;
var presentMembers = [16, 14];

// Check if quorum exists
if (presentMembers.length < quorumThreshold) {
    @answer "Quorum not met"
} else {
    // Assign tasks to students
    var assignments = [];
    for (var i = 0; i < students.length; i++) {
        var task = allowedTasks[Math.floor(Math.random() * allowedTasks.length)];
        assignments.push({ student: students[i], task: task });
    }

    // Check if all tasks are used
    var allTasksUsed = true;
    for (var i = 0; i < tasks.length; i++) {
        if (!assignments[i].task) {
            allTasksUsed = false;
            break;
        }
    }

    // Output the assignment
    @answer assignments
}
```

